import{_ as e,c as t,o as r,a0 as i}from"./chunks/framework._Jgw3yL-.js";const o="/HAWKZ-KEYBOARD/%E5%90%84%E7%B1%BB%E9%94%AE%E5%B8%BD%E9%AB%98%E5%BA%A6.png",s="/HAWKZ-KEYBOARD/%E9%94%AE%E5%B8%BD%E6%94%B6%E9%9F%B3%E5%81%8F%E6%96%B9.png",E=JSON.parse('{"title":"基础-客制化键盘外壳与内胆","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/HAWKZ-jelly102-CN/键帽类型.md","filePath":"zh-CN/HAWKZ-jelly102-CN/键帽类型.md"}'),l={name:"zh-CN/HAWKZ-jelly102-CN/键帽类型.md"};function d(m,a,c,n,p,_){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="基础-客制化键盘外壳与内胆" tabindex="-1">基础-客制化键盘外壳与内胆 <a class="header-anchor" href="#基础-客制化键盘外壳与内胆" aria-label="Permalink to &quot;基础-客制化键盘外壳与内胆&quot;">​</a></h1><div class="image-row image-row-2"><div class="image-item"><img src="'+o+'" alt="键帽类型" class="zoom-medium"><div>键帽高度</div></div></div><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2><p>键帽高度对机械键盘声音影响显著：键帽越高、越重，腔体共鸣空间越大，声音通常更低沉、浑厚（如SA、MA高度）；键帽越低、越轻，声音通常更清脆、响亮（如Cherry、OEM高度）。此外，厚键帽能吸收杂音，使声音更集中</p><p><a href="https://post.smzdm.com/p/az67gv95/" target="_blank" rel="noreferrer">https://post.smzdm.com/p/az67gv95/</a></p><h2 id="键帽收音偏方" tabindex="-1">键帽收音偏方 <a class="header-anchor" href="#键帽收音偏方" aria-label="Permalink to &quot;键帽收音偏方&quot;">​</a></h2><p>效果 对打字音的提升比润轴内大多了。可以让回弹声音更低沉，接近雨滴声。</p><p>方法 用手里最稠的润滑脂随便涂在键帽里的四个角落就行，比润轴方便多了。</p><p>理论 厚润改善声音本就是靠润滑脂吸收轴体的震动减少声音，润了半天轴发现对声音影响最大的其实是键帽。手里的是原厂高度，为了声音单独换键帽不合算，就试着用昆仑2号涂在里面，效果显著。</p><div class="image-row image-row-2"><div class="image-item"><img src="'+s+'" alt="键帽收音" class="zoom-medium"><div>手法</div></div></div>',10)])])}const A=e(l,[["render",d]]);export{E as __pageData,A as default};
